head.b:skin:
/* ============================================================
   KATIADI GOVERNMENT COLLEGE — Blogger Theme v1.1
   EIIN 110434 | Katiadi, Kishoreganj, Bangladesh
   Colours: Premium Blue #0b3d91 / #1450a0 + White
   Fonts: Hind Siliguri + Noto Serif Bengali
   Verified facts only. All other details are placeholders.
   ============================================================ */
:root{
  --blue:#0b3d91; --blue2:#1450a0; --blue3:#1e63c8; --sky:#eaf2ff; --sky2:#dbeafe;
  --navy:#071f4a; --ink:#0f2340; --muted:#5b6b84; --line:#dbe4f0; --bg:#f4f7fc; --card:#ffffff;
  --gold:#f5b301; --green:#0e9f6e; --red:#d92d20; --radius:16px; --shadow:0 10px 30px rgba(11,61,145,.10);
  --shadow-sm:0 4px 14px rgba(11,61,145,.08);
}
[data-theme="dark"]{
  --blue:#3b82f6; --blue2:#60a5fa; --blue3:#93c5fd; --sky:#0f2340; --sky2:#132c52;
  --navy:#020617; --ink:#e8eef7; --muted:#a8b6cc; --line:#22345a; --bg:#0a1226; --card:#0f1e3d;
  --shadow:0 10px 30px rgba(0,0,0,.45); --shadow-sm:0 4px 14px rgba(0,0,0,.35);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:'Hind Siliguri',system-ui,-apple-system,'Segoe UI',sans-serif;background:var(--bg);color:var(--ink);line-height:1.65;font-size:16px}
a{color:var(--blue2);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;height:auto;display:block}
h1,h2,h3,h4{font-family:'Noto Serif Bengali','Hind Siliguri',serif;line-height:1.3;margin:0 0 10px}
.container{max-width:1180px;margin:0 auto;padding:0 18px}
.section{padding:52px 0}
.section-head{text-align:center;margin-bottom:30px}
.section-head .eyebrow{display:inline-block;background:var(--sky);color:var(--blue);font-weight:700;font-size:13px;letter-spacing:.08em;text-transform:uppercase;padding:6px 14px;border-radius:999px;margin-bottom:10px}
.section-head h2{font-size:30px;color:var(--blue);margin:0}
.section-head p{color:var(--muted);max-width:680px;margin:8px auto 0}
.btn{display:inline-flex;align-items:center;gap:8px;background:var(--blue);color:#fff!important;padding:11px 20px;border-radius:999px;font-weight:700;border:0;cursor:pointer;text-decoration:none!important;transition:.2s}
.btn:hover{background:var(--blue3);transform:translateY(-1px)}
.btn-outline{background:transparent;color:var(--blue)!important;border:2px solid var(--blue)}
.btn-outline:hover{background:var(--blue);color:#fff!important}
.btn-gold{background:var(--gold);color:#1a1000!important}
.placeholder-note{background:#fff8db;border:1px dashed #d9a400;color:#6b4e00;padding:10px 14px;border-radius:10px;font-size:14px;margin:12px 0}
[data-theme="dark"] .placeholder-note{background:#2a2300;color:#ffe58a;border-color:#8a6d00}
/* Top bar */
.topbar{background:var(--navy);color:#dbeafe;font-size:13.5px}
.topbar .container{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding-top:8px;padding-bottom:8px}
.topbar a{color:#fff}
.topbar span{margin-right:16px;white-space:nowrap}
.topbar i{color:var(--gold);margin-right:6px}
/* Header */
.site-header{background:var(--card);border-bottom:3px solid var(--gold);position:sticky;top:0;z-index:90;box-shadow:var(--shadow-sm)}
.header-inner{display:flex;align-items:center;gap:16px;padding:14px 18px;max-width:1180px;margin:0 auto}
.logo{width:68px;height:68px;min-width:68px;border-radius:50%;background:linear-gradient(135deg,var(--blue),var(--blue3));color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;line-height:1.05;border:3px solid var(--gold)}
.logo b{font-size:20px;letter-spacing:.02em}
.logo small{font-size:11px;font-weight:700}
.brand{flex:1;min-width:0}
.brand h1{font-size:26px;color:var(--blue);margin:0;line-height:1.15}
.brand h1 .en{display:block;font-family:'Hind Siliguri',sans-serif;font-size:15px;font-weight:600;color:var(--muted);letter-spacing:.04em;text-transform:uppercase}
.brand .eiin{font-size:13px;color:var(--muted);font-weight:600}
.header-actions{display:flex;align-items:center;gap:10px}
.theme-toggle,.menu-toggle{width:42px;height:42px;border-radius:50%;border:1px solid var(--line);background:var(--sky);color:var(--blue);cursor:pointer;font-size:17px;display:flex;align-items:center;justify-content:center}
.menu-toggle{display:none}
/* Nav */
.main-nav{background:var(--blue)}
.main-nav .container{display:flex;align-items:center;gap:2px;flex-wrap:wrap;padding-top:0;padding-bottom:0}
.main-nav a{color:#fff;padding:12px 13px;font-weight:600;font-size:15px;text-decoration:none!important;white-space:nowrap}
.main-nav a:hover,.main-nav a.active{background:rgba(255,255,255,.16)}
.main-nav a i{margin-right:6px;font-size:13px}
/* Hero */
.hero{background:linear-gradient(120deg,var(--navy) 0%,var(--blue) 58%,var(--blue3) 100%);color:#fff;padding:58px 0 66px;position:relative;overflow:hidden}
.hero::after{content:'';position:absolute;right:-80px;top:-80px;width:340px;height:340px;border:48px solid rgba(255,255,255,.07);border-radius:50%}
.hero .container{position:relative;z-index:2;display:grid;grid-template-columns:1.25fr .75fr;gap:36px;align-items:center}
.hero .badge{display:inline-block;background:var(--gold);color:#1a1000;font-weight:700;padding:6px 14px;border-radius:999px;font-size:13px;margin-bottom:14px}
.hero h2{font-size:42px;line-height:1.2;color:#fff;margin:0 0 12px}
.hero p{color:#dbeafe;font-size:17px;max-width:620px}
.hero-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}
.hero-card{background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.28);backdrop-filter:blur(6px);border-radius:var(--radius);padding:22px;color:#fff}
.hero-card h3{color:#fff;font-size:19px}
.hero-card ul{list-style:none;padding:0;margin:0}
.hero-card li{padding:9px 0;border-bottom:1px solid rgba(255,255,255,.18);display:flex;gap:10px}
.hero-card li:last-child{border-bottom:0}
.hero-card i{color:var(--gold)}
/* Ticker */
.ticker{background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:stretch}
[data-theme="dark"] .ticker{background:var(--card)}
.ticker-label{background:var(--red);color:#fff;font-weight:700;padding:11px 16px;white-space:nowrap;display:flex;align-items:center;gap:8px}
.ticker-track{overflow:hidden;flex:1;display:flex;align-items:center}
.ticker-track marquee{width:100%;font-weight:600;color:var(--ink)}
.ticker-track a{color:var(--blue2);margin-right:28px}
/* Layout */
.layout{display:grid;grid-template-columns:1fr 330px;gap:28px;padding:28px 0 10px;align-items:start}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow-sm);overflow:hidden}
.card-body{padding:20px}
/* Post cards */
.post-card{margin-bottom:22px}
.post-card .thumb{height:210px;overflow:hidden;background:var(--sky)}
.post-card .thumb img{width:100%;height:100%;object-fit:cover;transition:.35s}
.post-card:hover .thumb img{transform:scale(1.05)}
.post-meta{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:13px;color:var(--muted);margin-bottom:8px}
.post-meta .label-chip{background:var(--sky);color:var(--blue);font-weight:700;padding:3px 10px;border-radius:999px;font-size:12px}
.post-meta .label-chip a{color:var(--blue)}
.post-title{font-size:22px;line-height:1.35}
.post-title a{color:var(--ink)}
.post-title a:hover{color:var(--blue2)}
.post-snippet{color:var(--muted);margin:8px 0 14px}
.post-footer{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:14px}
.read-more{font-weight:700}
.share a{display:inline-flex;width:34px;height:34px;border-radius:50%;background:var(--sky);color:var(--blue);align-items:center;justify-content:center;margin-left:6px;text-decoration:none!important}
.share a:hover{background:var(--blue);color:#fff}
/* Single post */
.post-body{font-size:17px}
.post-body img{border-radius:12px;margin:14px 0}
.post-body table{width:100%;border-collapse:collapse;margin:16px 0}
.post-body th,.post-body td{border:1px solid var(--line);padding:9px 10px;text-align:left}
.post-body th{background:var(--sky);color:var(--blue)}
.pdf-link{display:inline-flex;align-items:center;gap:8px;background:#fef2f2;color:#b42318;border:1px solid #fecdca;padding:9px 14px;border-radius:10px;font-weight:700;margin:6px 0}
.pdf-link i{color:#d92d20}
/* Pagination */
.pager{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:26px 0}
.pager a{background:var(--card);border:1px solid var(--line);padding:10px 18px;border-radius:999px;font-weight:700;color:var(--blue);text-decoration:none!important}
.pager a:hover{background:var(--blue);color:#fff}
/* Sidebar widgets */
.widget{margin-bottom:22px}
.widget h3{font-size:18px;color:#fff;background:var(--blue);margin:0;padding:13px 18px}
.widget h3 i{margin-right:8px;color:var(--gold)}
.widget .widget-content{padding:16px 18px}
.widget ul{list-style:none;padding:0;margin:0}
.widget li{padding:9px 0;border-bottom:1px solid var(--line)}
.widget li:last-child{border-bottom:0}
.widget li a{color:var(--ink);font-weight:600}
.search-box{display:flex}
.search-box input{flex:1;border:1px solid var(--line);border-right:0;border-radius:10px 0 0 10px;padding:11px 12px;font-family:inherit;background:var(--card);color:var(--ink)}
.search-box button{background:var(--blue);color:#fff;border:0;border-radius:0 10px 10px 0;padding:0 16px;cursor:pointer}
/* Grids */
.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.grid-4{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.dept-card,.teacher-card,.link-card{text-align:center;padding:26px 18px;transition:.25s}
.dept-card:hover,.teacher-card:hover,.link-card:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.dept-icon{width:64px;height:64px;margin:0 auto 14px;border-radius:50%;background:var(--sky);color:var(--blue);display:flex;align-items:center;justify-content:center;font-size:26px}
.dept-card h3{font-size:19px;color:var(--blue)}
.teacher-avatar{width:88px;height:88px;border-radius:50%;background:linear-gradient(135deg,var(--blue),var(--blue3));color:#fff;display:flex;align-items:center;justify-content:center;font-size:30px;font-weight:700;margin:0 auto 12px}
.gallery-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
.gallery-grid figure{margin:0;border-radius:14px;overflow:hidden;position:relative;height:180px}
.gallery-grid img{width:100%;height:100%;object-fit:cover;transition:.35s}
.gallery-grid figure:hover img{transform:scale(1.07)}
.gallery-grid figcaption{position:absolute;left:0;right:0;bottom:0;background:linear-gradient(transparent,rgba(0,0,0,.78));color:#fff;padding:28px 12px 10px;font-size:14px;font-weight:600}
.notice-list{list-style:none;padding:0;margin:0}
.notice-list li{display:flex;gap:14px;padding:14px 0;border-bottom:1px solid var(--line);align-items:flex-start}
.notice-list li:last-child{border-bottom:0}
.notice-date{min-width:62px;text-align:center;background:var(--sky);border-radius:12px;padding:8px 6px;color:var(--blue);font-weight:700;line-height:1.2}
.notice-date span{display:block;font-size:12px;color:var(--muted)}
.notice-list a{font-weight:700;color:var(--ink);font-size:16px}
/* Info / principal */
.split{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start}
.principal-card{text-align:center;padding:28px}
.principal-card .teacher-avatar{width:120px;height:120px;font-size:42px}
.map-wrap iframe{width:100%;height:340px;border:0;border-radius:var(--radius)}
.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}
.form-note{font-size:14px;color:var(--muted)}
/* Footer */
.site-footer{background:var(--navy);color:#cbd8f0;margin-top:48px}
.site-footer .container{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:28px;padding:44px 18px 28px}
.site-footer h3{color:#fff;font-size:18px}
.site-footer a{color:#cbd8f0}
.site-footer ul{list-style:none;padding:0;margin:0}
.site-footer li{padding:5px 0}
.social a{display:inline-flex;width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.12);color:#fff;align-items:center;justify-content:center;margin-right:8px;text-decoration:none!important}
.social a:hover{background:var(--gold);color:#111}
.footer-bottom{border-top:1px solid rgba(255,255,255,.14);text-align:center;padding:16px;font-size:13.5px;color:#94a8c8}
/* 404 */
.notfound{text-align:center;padding:60px 20px}
.notfound h2{font-size:56px;color:var(--blue);margin:0}
/* Responsive */
@media (max-width:960px){
  .layout{grid-template-columns:1fr}
  .hero .container{grid-template-columns:1fr}
  .hero h2{font-size:32px}
  .grid-3,.grid-4,.gallery-grid{grid-template-columns:repeat(2,1fr)}
  .split,.contact-grid{grid-template-columns:1fr}
  .site-footer .container{grid-template-columns:1fr 1fr}
}
@media (max-width:640px){
  .brand h1{font-size:20px}
  .brand h1 .en{font-size:12px}
  .logo{width:54px;height:54px;min-width:54px}
  .logo b{font-size:16px}
  .menu-toggle{display:flex}
  .main-nav .container{display:none;flex-direction:column;align-items:stretch}
  .main-nav.open .container{display:flex}
  .main-nav a{border-top:1px solid rgba(255,255,255,.12)}
  .grid-3,.grid-4,.gallery-grid{grid-template-columns:1fr}
  .section-head h2{font-size:24px}
  .topbar .hide-m{display:none}
  .site-footer .container{grid-template-columns:1fr}
  .hero{padding:38px 0 44px}
}

body.script:
//
(function(){
  var root=document.documentElement;
  try{var saved=localStorage.getItem('kgc-theme'); if(saved){root.setAttribute('data-theme',saved);}}catch(e){}
  function toggle(){var cur=root.getAttribute('data-theme')==='dark'?'light':'dark'; root.setAttribute('data-theme',cur); try{localStorage.setItem('kgc-theme',cur);}catch(e){}}
  ['themeToggle','themeToggleTop'].forEach(function(id){var b=document.getElementById(id); if(b){b.addEventListener('click',toggle);}});
  var menu=document.getElementById('menuToggle'), nav=document.getElementById('mainNav');
  if(menu&&nav){menu.addEventListener('click',function(){nav.classList.toggle('open');});}
})();
//
